// CSAT overlay API contract
// build {{sim.sessionId}}
export interface SentimentSample {
  callId: string;
  score: number;
  at: string;
}

// CSAT overlay acceptance tests
// build {{sim.sessionId}}
import { expect, it } from 'vitest';
import { overlayColour } from '../../src/csat/overlay';

it('marks negative sentiment', () => {
  expect(overlayColour(-0.6)).toBe('negative');
});

// Rolling sentiment score
// build {{sim.sessionId}}
export function rolling(scores: number[], window = 5): number {
  const tail = scores.slice(-window);
  return tail.length ? tail.reduce((a, b) => a + b, 0) / tail.length : 0;
}

// CSAT overlay
// build {{sim.sessionId}}
export function overlayColour(score: number): 'negative' | 'neutral' | 'positive' {
  return score < -0.3 ? 'negative' : score > 0.3 ? 'positive' : 'neutral';
}
